package br.com.conectatea.vinculo.domain;
import br.com.conectatea.shared.domain.AuditableEntity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="vinculos_profissionais_criancas",uniqueConstraints=@UniqueConstraint(columnNames={"profissional_id","crianca_id"}))
public class VinculoProfissionalCrianca extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="profissional_id",nullable=false) private Long profissionalId; @Column(name="crianca_id",nullable=false) private Long criancaId; @Enumerated(EnumType.STRING) @Column(nullable=false) private StatusVinculo status; @Column(name="data_vinculo") private Instant dataVinculo; @Column(name="data_desvinculo") private Instant dataDesvinculo; @Column(name="motivo_desvinculo") private String motivoDesvinculo; protected VinculoProfissionalCrianca(){} public VinculoProfissionalCrianca(Long p,Long c){profissionalId=p;criancaId=c;status=StatusVinculo.VINCULADO;dataVinculo=Instant.now();} public Long getProfissionalId(){return profissionalId;} public Long getCriancaId(){return criancaId;} public StatusVinculo getStatus(){return status;} }
